function adexStep(n, I, dt, p) {
  // p = { C: 281, gL: 30, EL: -70.6, VT: -50.4, dT: 2, a: 4, b: 80.5, tauW: 144, Vr: -70.6, Vpeak: 20 }
  const exp = p.gL * p.dT * Math.exp(Math.min((n.v - p.VT) / p.dT, 30));
  const dv = (-p.gL * (n.v - p.EL) + exp - n.w + I) / p.C;
  const dw = (p.a * (n.v - p.EL) - n.w) / p.tauW;
  n.v += dt * dv;  n.w += dt * dw;
  if (n.v >= p.Vpeak) { n.v = p.Vr; n.w += p.b; return true; }
  return false;
}
